import re
import json

def parse_script(text: str):
    nodes = []
    edges = []

    # Split text into blocks based on [NodeId]
    raw_blocks = re.split(r'\[(.*?)\]', text)

    node_ids_in_script = set()

    for i in range(1, len(raw_blocks), 2):
        node_id = raw_blocks[i].strip()
        content = raw_blocks[i+1].strip()

        if not content:
            # Some nodes might be empty or just targets
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            node_ids_in_script.add(node_id)
            continue

        lines = [l.strip() for l in content.split('\n') if l.strip()]
        if not lines:
            nodes.append({
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            node_ids_in_script.add(node_id)
            continue

        # Determine if it's a choice node or a line node
        # Choice nodes start with "1."
        if re.match(r'^\d+\.', lines[0]):
            node = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            nodes.append(node)
            node_ids_in_script.add(node_id)
            for line in lines:
                match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', line)
                if match:
                    choice_text = match.group(1).strip()
                    target = match.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            # Line node
            # Format: Speaker: Text -> Target
            line = lines[0]
            node = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "line"
            }
            match = re.match(r'^(.*?):\s*(.*?)\s*->\s*(.*)$', line)
            if match:
                speaker = match.group(1).strip()
                text_content = match.group(2).strip()
                target = match.group(3).strip()
                node["speaker"] = speaker
                node["text"] = text_content
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": ""
                })
            else:
                # Try without speaker
                match = re.match(r'^(.*?)\s*->\s*(.*)$', line)
                if match:
                    text_content = match.group(1).strip()
                    target = match.group(2).strip()
                    node["text"] = text_content
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": ""
                    })
            nodes.append(node)
            node_ids_in_script.add(node_id)

    # Add missing nodes that are targets but not defined as blocks
    all_targets = set(edge["to"] for edge in edges)
    for target in all_targets:
        if target not in node_ids_in_script:
            nodes.append({
                "id": target,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            node_ids_in_script.add(target)

    # Filter reachable nodes from the first node
    if not nodes:
        return {"nodes": [], "edges": []}

    first_node_id = nodes[0]["id"]
    reachable = {first_node_id}
    queue = [first_node_id]

    edge_map = {}
    for edge in edges:
        if edge["from"] not in edge_map:
            edge_map[edge["from"]] = []
        edge_map[edge["from"]].append(edge["to"])

    while queue:
        curr = queue.pop(0)
        for neighbor in edge_map.get(curr, []):
            if neighbor not in reachable:
                reachable.add(neighbor)
                queue.append(neighbor)

    final_nodes = [n for n in nodes if n["id"] in reachable]
    final_edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": final_nodes, "edges": final_edges}

def generate_dot(graph):
    dot = ["digraph Dialogue {"]
    dot.append("  node [shape=rect, style=filled, color=lightblue];")

    for node in graph["nodes"]:
        node_id = node["id"]
        if node["type"] == "choice":
            label = f"{node_id}\\n(Choice)"
        elif node["speaker"]:
            text = node["text"].replace('"', '\\"')
            label = f"{node_id}\\n{node['speaker']}: {text}"
        elif node["text"]:
            text = node["text"].replace('"', '\\"')
            label = f"{node_id}\\n{text}"
        else:
            label = node_id

        dot.append(f'  "{node_id}" [label="{label}"];')

    for edge in graph["edges"]:
        if edge["text"]:
            label = edge["text"].replace('"', '\\"')
            dot.append(f'  "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')
        else:
            dot.append(f'  "{edge["from"]}" -> "{edge["to"]}";')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    import sys
    import os

    input_file = "/app/script.txt"
    if not os.path.exists(input_file):
        print(f"Error: {input_file} not found.")
        sys.exit(1)

    with open(input_file, 'r') as f:
        script_content = f.read()

    graph = parse_script(script_content)

    with open("/app/dialogue.json", "w") as f:
        json.dump(graph, f, indent=2)

    dot_content = generate_dot(graph)
    with open("/app/dialogue.dot", "w") as f:
        f.write(dot_content)

